function download(name:string,content:string,type="text/plain"){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement("a");a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function csvValue(v:unknown){return '"'+String(v??"").replaceAll('"','""')+'"';}
function parseCSV(text:string){const rows:string[][]=[];let fields:string[]=[],field="",quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){field+='"';i++;}else quoted=!quoted;}else if(c===","&&!quoted){fields.push(field);field="";}else if((c==="\n"||c==="\r")&&!quoted){if(c==="\r"&&text[i+1]==="\n")i++;fields.push(field);if(fields.some(x=>x.trim()))rows.push(fields);fields=[];field="";}else field+=c;}if(quoted)throw new Error("The CSV has an unclosed quote.");fields.push(field);if(fields.some(x=>x.trim()))rows.push(fields);const headers=rows.shift()?.map(s=>s.trim().replace(/^\uFEFF/,""))||[];const required=["site","period","metric","numerator","denominator","source","note"];if(required.some(h=>!headers.includes(h)))throw new Error("The CSV must contain: "+required.join(", "));return rows.map(r=>Object.fromEntries(headers.map((h,i)=>[h,r[i]??""])) as unknown as Entry);}
