function Status({value}:{value:string}){return <span className={"status status-"+(value==="On target"||value==="approved"||value==="Sample approved"?"good":value==="Action"||value==="rejected"?"bad":value==="No data"||value==="No site target"?"neutral":"watch")}>{value}</span>;}
function Panel({title,sub,children,action,className=""}:{title:string;sub?:string;children:React.ReactNode;action?:React.ReactNode;className?:string}){return <section className={"panel "+className}><div className="panel-head"><div><h2>{title}</h2>{sub&&<p>{sub}</p>}</div>{action}</div>{children}</section>;}
function Empty({title,body}:{title:string;body:string}){return <div className="empty-state"><Database size={28}/><h3>{title}</h3><p>{body}</p></div>;}

