 const [productTab,setProductTab]=useState("modules"),[docFiles,setDocFiles]=useState<{id:string;title:string;filename:string;department:string;status:string;size:number}[]>([]),[docDept,setDocDept]=useState("Operations"),[docUploading,setDocUploading]=useState(false);
