 useEffect(()=>{let active=true;setData(null);setLoading(true);setError("");fetch(`/api/platform?${query}`,{cache:"no-store"}).then(async r=>{const j=await r.json() as Data & {error?:string};if(!r.ok)throw new Error(j.error);if(active)setData(j);}).catch(e=>{if(active)setError(e.message);}).finally(()=>{if(active)setLoading(false);});return()=>{active=false;};},[query]);
