 const importCSV=async(file:File)=>{try{const parsed=parseCSV(await file.text());if(!parsed.length||parsed.length>40)throw new Error("Import 1–40 rows per batch.");for(const r of parsed){if(!metrics.some(m=>m.id===r.metric)||!sites.includes(r.site)||!validPeriod(r.period))throw new Error("A CSV row is outside the role's visible metrics, sites or months.");const m=metrics.find(m=>m.id===r.metric)!;const n=Number(r.numerator),d=Number(r.denominator);if(r.numerator===""||r.denominator===""||!Number.isFinite(n)||!Number.isFinite(d)||d<0||(n<0&&m.id!=="margin"&&m.method!=="value")||(!["sum","value"].includes(m.method)&&d<=0)||(m.method==="value"&&d!==1)||(m.method==="ratio"&&n>d)||r.source.trim().length<5)throw new Error("A row has invalid numbers or a missing source reference.");}for(const r of parsed){r.details=Object.fromEntries((data?.fields||[]).filter(f=>!f.metricId||f.metricId===r.metric).map(f=>[f.key,(r as unknown as Record<string,string>)[f.key]||""]));}setImportRows(parsed);setImportOpen(true);}catch(e){toast.error(e instanceof Error?e.message:"Invalid CSV.");}};
 const uploadDoc=async(file:File)=>{setDocUploading(true);try{const form=new FormData();form.set("file",file);form.set("department",departments.includes(docDept)?docDept:departments[0]);form.set("title",file.name);form.set("site",site==="all"?"company":site);const r=await fetch(`/api/documents?${query}`,{method:"POST",body:form});const j=await r.json() as {error?:string;file:typeof docFiles[number]};if(!r.ok)throw new Error(j.error);setDocFiles(v=>[j.file,...v]);toast.success("File stored in the review queue. It is not yet AI or bid evidence.");}catch(e){toast.error(e instanceof Error?e.message:"Upload failed.");}finally{setDocUploading(false);}};
